  const tTop = (x, y, k) => [
    cup(x + 16, y + 14) + `<ellipse cx="${x + 38}" cy="${y + 10}" rx="10" ry="7.4" fill="${CREAM}" ${L}/><path d="M${x + 48} ${y + 8} q5 -2 5 -6" fill="none" stroke="${CREAM}" stroke-width="2.4"/><circle cx="${x + 38}" cy="${y + 3}" r="1.8" fill="${CREAM}" ${L}/>`,
    `<rect x="${x + 26}" y="${y + 2}" width="8" height="10" rx="2" fill="#CFE3EA" opacity=".9" ${L}/><circle cx="${x + 28}" cy="${y}" r="2.6" fill="#E58AA8"/><circle cx="${x + 33}" cy="${y - 2}" r="2.6" fill="#E58AA8"/>` + cup(x + 14, y + 18, "#F4C7CF") + cup(x + 46, y + 18, "#C3DDF3"),
    `<ellipse cx="${x + 22}" cy="${y + 13}" rx="10" ry="4" fill="${CREAM}" ${L}/><path d="M${x + 16} ${y + 12} l8 -6 l4 6z" fill="#F6E3A0" ${L}/><path d="M${x + 17} ${y + 10} l8 -4" stroke="${BUCK[0]}" stroke-width="1.6"/>` + jar(x + 44, y + 18, BUCK[0], 9, 12)][k];
